51 :         tryMinimizeExits(
52 :             n.getLastChild(), Token.BREAK, n.getFirstChild().getString());
53 :         break;
54 : 
55 :       case Token.FOR:
56 :       case Token.WHILE:
57 :         tryMinimizeExits(NodeUtil.getLoopCodeBlock(n), Token.CONTINUE, null);
58 :         break;
59 : 
