61 :         tryMinimizeExits(NodeUtil.getLoopCodeBlock(n), Token.CONTINUE, null);
62 : 
63 :         Node cond = NodeUtil.getConditionExpression(n);
64 :         if (NodeUtil.getImpureBooleanValue(cond) == TernaryValue.FALSE) {
65 :           // Normally, we wouldn't be able to optimize BREAKs inside a loop
66 :           // but as we know the condition will always false, we can treat them
67 :           // as we would a CONTINUE.
68 :           tryMinimizeExits(n.getFirstChild(), Token.BREAK, null);
69 :         }
70 :         break;
71 : 
72 :       case Token.FUNCTION:
73 :         tryMinimizeExits(n.getLastChild(), Token.RETURN, null);
74 :         break;
75 :     }
